function npx(pkg, more, extra) {
  return Object.assign({ command: 'npx', args: ['-y'].concat(pkg, more || []) }, extra || {});
}
function uvx(pkg, more, extra) {
  return Object.assign({ command: 'uvx', args: [pkg].concat(more || []) }, extra || {});
}
function remote(url, extra) {
  return Object.assign({ url }, extra || {});
}
function off(spec) {
  return Object.assign({}, spec, { disabled: true });
}

