const loopback = (port) => remote(`http://127.0.0.1:${port}/mcp`);
const loopback6 = () => remote('http://[::1]:7331/mcp');

function tools(names) {
  return names.map(name => ({ name, description: name.replace(/_/g, ' ') }));
}

function row(id, client, expected, rationale, sources, servers, note) {
  return {
    id,
    client,
    expectedSeverities: expected,
    rationale,
    sources,
    servers,
    note: note || '',
  };
}

